INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How to Stay Employed in the Age of AI .: AWS Crystal City, VA :.', 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 'Founders & Startups', 'Join us for a discussion about building a long-lasting career in today''s fast-changing world of AI. Another certificate won''t save your', 'Join us for a discussion about building a long-lasting career in today''s fast-changing world of AI. Another certificate won''t save your career. Proof will. Host Soo-Jin Lee talks with William Zhu, AI thought leader and data scientist, about his book *Proof Over Promise*. He''ll share what actually keeps people employable in the AI age. Bring your questions. This is a conversation, not a lecture. **Featured speaker:** * [William Zhu](https://www.linkedin.com/in/william-wei-zhu/)\, Applied AI More info: https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316595540/', '2026-10-28T18:00:00-04:00', 'AWS Skills Center Arlington', '1550-G Crystal Dr, Arlington, VA 22202, USA', 'Arlington', 'VA', '22202', 38.860249324963, -77.049379864862, 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 133, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316595540/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('CodeRabbit Hosts: Pizza & Networking at Andy''s in Tyson''s Galleria : Tysons, VA', 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 'Founders & Startups', 'Hello everyone! Who doesn''t love Pizza! We''ll be meeting at Andy''s Pizza in Tyson''s Galleria and doing some old-fashioned networking,', 'Hello everyone! Who doesn''t love Pizza! We''ll be meeting at Andy''s Pizza in Tyson''s Galleria and doing some old-fashioned networking, beer-drinking, and pizza-eating. For this event, Pizza and the fun will be sponsored by CodeRabbit! **About CodeRabbit**: CodeRabbit helps software teams ship faster without lowering the bar for quality. As people and AI coding agents produce more code, teams need a reliable way to understand and review those changes. CodeRabbit’s approach is Agentic Change More info: https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316580824/', '2026-11-11T19:00:00-05:00', 'Andy''s Pizza', '2001 International Dr,', 'McLean', 'VA', '', 38.89, -77.1, 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 57, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316580824/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('AI Policy and the Race for Global Rules .: AWS-Crystal City, Virginia :.', 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 'Founders & Startups', 'AI governance has become a matter of international diplomacy. In the past few weeks, the UN Security Council held a high-level briefing on', 'AI governance has become a matter of international diplomacy. In the past few weeks, the UN Security Council held a high-level briefing on AI risk where leaders from major AI companies called for global regulation. Separately, a group of about 20 countries proposed an international oversight body to manage the dangers of AI. Join us for a globe-trotting discussion on where AI policy is heading around the world. We''ll see how the EU, the U.S., China, the UK and other countries are regulating AI, More info: https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316754858/', '2026-11-18T18:00:00-05:00', 'AWS Skills Center Arlington', '1550-G Crystal Dr, Arlington, VA 22202, USA', 'Arlington', 'VA', '22202', 38.860249324963, -77.049379864862, 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 36, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316754858/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('AI Wrote the Code. Should You Ship It? .: AWS Crystal City, VA :.', 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 'Founders & Startups', 'AI coding agents can produce changes faster than teams can review them. In this interactive session, we’ll explore how to keep that speed', 'AI coding agents can produce changes faster than teams can review them. In this interactive session, we’ll explore how to keep that speed while making confident decisions about quality and risk. We’ll use CodeRabbit’s agentic change management framework—validate, prioritize, explain, and secure—to examine what needs to happen between a generated change and a decision to ship. A proposed hands-on format: walk through a sample AI-generated pull request, have the group decide what they would More info: https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316895947/', '2026-12-02T18:00:00-05:00', 'AWS Skills Center Arlington', '1550-G Crystal Dr, Arlington, VA 22202, USA', 'Arlington', 'VA', '22202', 38.860249324963, -77.049379864862, 'AI Innovators Network ~ Northern Virginia .: DC, VA, MD :.', 30, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/ai-innovators-network-tysons-meetup-dc-nova-md/events/316895947/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
