INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('ATLSUDs @ Argosy', 'Atlanta Startup Drinks', 'Founders & Startups', 'Join us at Argosy for our monthly get-together! Since 2012, ATLSUDs has been a go-to spot for folks looking to share startup wins, and', 'Join us at Argosy for our monthly get-together! Since 2012, ATLSUDs has been a go-to spot for folks looking to share startup wins, and lessons learned, or simply commiserate about the journey. The environment is casual—stop by whenever you can, stay as long as you like. Bring your team or come solo. You’ll find a community eager to offer feedback and celebrate each other’s milestones, big or small. **Date**: November 4, 2026 (Wednesday) **Time**: 5:00pm – 8:00(ish) **Location**: Argosy More info: https://www.meetup.com/atlanta-startup-drinks/events/316553306/', '2026-11-04T17:00:00-05:00', 'Argosy', '470 Flat Shoals Ave SE, Atlanta, GA 30316, USA', 'Atlanta', 'GA', '30316', 33.741291411872, -84.346523396338, 'Atlanta Startup Drinks', 5, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/atlanta-startup-drinks/events/316553306/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('U.S. Visas & Immigration 101 for Startup Founders', 'Atlanta Startup Founder 101', 'Founders & Startups', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never designed with startups in mind. This 101 session breaks down the essentials in plain English. You''ll get a clear map of the visa paths open to founders, how they differ, and what each one actually asks of you when you''re the one building the company. We''ll also look at how milestones like fundraising and revenue shape your options, and the mistakes that quietly More info: https://www.meetup.com/atlanta-startup-founder-101/events/316753086/', '2026-10-12T12:00:00-04:00', 'Online event', 'Online event', 'Atlanta', 'GA', '', 33.75, -84.39, 'Atlanta Startup Founder 101', 4, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/atlanta-startup-founder-101/events/316753086/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('From Dreamer to Doer: Build the Founder Mindset', 'Atlanta Startup Founder 101', 'Founders & Startups', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the', 'Have you ever wondered why some people take the leap while others stay stuck? The difference isn''t luck, resources, or timing — it''s the way founders think. Join Jonathan Greechan, Co-Founder & CEO of the Founder Institute, for a fascinating deep-dive into the psychology behind entrepreneurial action. In this live session, you''ll unpack the cognitive patterns that hold aspiring founders back and explore the mental frameworks that top entrepreneurs use to push through uncertainty. With practical More info: https://www.meetup.com/atlanta-startup-founder-101/events/316598576/', '2026-10-13T12:00:00-04:00', 'Online event', 'Online event', 'Atlanta', 'GA', '', 33.75, -84.39, 'Atlanta Startup Founder 101', 4, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/atlanta-startup-founder-101/events/316598576/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How to Use AI to Position Your Startup to Buyers', 'Atlanta Startup Founder 101', 'Founders & Startups', 'You built the product. The market isn''t buying it yet. Usually the gap is positioning: buyers don''t see themselves in your pitch. **In this', 'You built the product. The market isn''t buying it yet. Usually the gap is positioning: buyers don''t see themselves in your pitch. **In this hands-on session, Jonathan Grover shows you how to use AI to fix that. You''ll build a synthetic version of your ideal buyer as an AI agent, then let it tear into your pitch in real time, surfacing the objections and gaps a real buyer would raise.** You''ll leave with sharper positioning that actually converts, plus a Claude skill you can take home and reuse More info: https://www.meetup.com/atlanta-startup-founder-101/events/316871853/', '2026-10-20T12:00:00-04:00', 'Online event', 'Online event', 'Atlanta', 'GA', '', 33.75, -84.39, 'Atlanta Startup Founder 101', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/atlanta-startup-founder-101/events/316871853/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
